# Generated by build.py from recipe.yml for recipe pop3-peek-at-headers-with-top. Do not edit.
Set-Location $PSScriptRoot
$server0 = Start-Process surl -ArgumentList '--mail-domain', 'example.com', '--mailbox', 'ann@example.com:annpass', '--mailbox', 'shop@example.com:shoppass', 'smtp://127.0.0.1:8080/', 'pop3://127.0.0.1:8081/' -PassThru -NoNewWindow
Start-Sleep 1
curl.exe -sS --crlf -u shop@example.com:shoppass --mail-from shop@example.com --mail-rcpt ann@example.com -T "order[1-3].eml" smtp://127.0.0.1:8080/example.com
curl.exe -sS --retry 10 --retry-all-errors --retry-delay 1 -u ann@example.com:annpass -X "LIST 3" pop3://127.0.0.1:8081/
try { curl.exe -u ann@example.com:annpass -X UIDL pop3://127.0.0.1:8081/ --next -u ann@example.com:annpass -X "TOP 2 0" pop3://127.0.0.1:8081/ } finally { Stop-Process $server0 }
